CREATE TABLE IF NOT EXISTS "professional_tax_slabs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid,
	"state_code" text NOT NULL,
	"state_name" text NOT NULL,
	"levies" boolean NOT NULL,
	"cadence" text,
	"slab_basis" text,
	"bands" jsonb,
	"annual_cap" numeric(14, 2),
	"last_period_adjustment" jsonb,
	"exemptions" jsonb,
	"due_date" jsonb,
	"source_type" text DEFAULT 'secondary' NOT NULL,
	"source_url" text,
	"verified_on" timestamp with time zone,
	"source_note" text,
	"dispute_note" text,
	"effective_from" timestamp with time zone NOT NULL,
	"effective_to" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
