-- R-1 wall (0052/0061 pattern): professional_tax_slabs carries org_id (nullable — org
-- overrides + platform defaults), so per rls-all-tables it must ENABLE + FORCE RLS with a
-- tenant_isolation policy. Nullable-org variant (cf. statutory_ceilings): platform-default
-- rows (org_id IS NULL) remain visible to every tenant, matching the resolver's
-- org-override → platform-default semantics. A no-op unless the request path drops to
-- app_runtime AND sets app.org_id (seeds/migrations/workers keep full access).
ALTER TABLE "professional_tax_slabs" ENABLE ROW LEVEL SECURITY;
